var PRODUCT_OPTION_LIMITS={types:3,values:20,variants:100,nameMax:30,labelMax:30};var OPTION_KINDS=["colour","size","custom"];var OPTION_ID_RE=/^o_[a-z0-9]{2,20}$/;var VALUE_ID_RE=/^v_[a-z0-9]{2,20}$/;var OPTION_HEX_RE=/^#[0-9a-fA-F]{6}$/;function optionText(value){return String(value==null?"":value).replace(/\s+/g," ").trim()}function validateProductOptions(raw,limits){limits=limits||PRODUCT_OPTION_LIMITS;if(!Array.isArray(raw)||raw.length===0)return{ok:false,error:"Add at least one option, such as Colour or Size.",field:"options"};if(raw.length>limits.types)return{ok:false,error:"Use at most "+limits.types+" option types.",field:"options"};var seenNames={},seenIds={},seenValueIds={};var out=[];for(var i=0;i<raw.length;i++){var o=raw[i]||{};var name=optionText(o.name);var id=String(o.id||"");var kind=OPTION_KINDS.indexOf(String(o.kind))!==-1?String(o.kind):"custom";if(!name)return{ok:false,error:"Give every option a name, such as Colour or Size.",field:"option:"+i};if(name.length>limits.nameMax)return{ok:false,error:"Keep option names to "+limits.nameMax+" characters.",field:"option:"+i};if(/[<>]/.test(name))return{ok:false,error:"Option names cannot contain < or >.",field:"option:"+i};if(seenNames[name.toLowerCase()])return{ok:false,error:'There are two options called "'+name+'".',field:"option:"+i};if(!OPTION_ID_RE.test(id)||seenIds[id])return{ok:false,error:'Option "'+name+'" is malformed. Please reload and try again.',field:"option:"+i};seenNames[name.toLowerCase()]=true;seenIds[id]=true;var values=Array.isArray(o.values)?o.values:[];if(!values.length)return{ok:false,error:'Add at least one value to "'+name+'".',field:"option:"+i};if(values.length>limits.values)return{ok:false,error:'"'+name+'" can have at most '+limits.values+" values.",field:"option:"+i};var seenLabels={};var cleanValues=[];for(var j=0;j<values.length;j++){var v=values[j]||{};var label=optionText(v.label);var vid=String(v.id||"");if(!label)return{ok:false,error:'A value of "'+name+'" is empty.',field:"value:"+i+":"+j};if(label.length>limits.labelMax)return{ok:false,error:"Keep values to "+limits.labelMax+" characters.",field:"value:"+i+":"+j};if(/[<>]/.test(label))return{ok:false,error:"Values cannot contain < or >.",field:"value:"+i+":"+j};if(seenLabels[label.toLowerCase()])return{ok:false,error:'"'+name+'" has "'+label+'" twice.',field:"value:"+i+":"+j};if(!VALUE_ID_RE.test(vid)||seenValueIds[vid])return{ok:false,error:'Value "'+label+'" is malformed. Please reload and try again.',field:"value:"+i+":"+j};seenLabels[label.toLowerCase()]=true;seenValueIds[vid]=true;var clean={id:vid,label:label};if(kind==="colour"&&v.hex&&OPTION_HEX_RE.test(String(v.hex)))clean.hex=String(v.hex).toLowerCase();cleanValues.push(clean)}out.push({id:id,name:name,kind:kind,values:cleanValues})}var count=countOptionCombinations(out);if(count>limits.variants){return{ok:false,error:"These options make "+count+" combinations - the most is "+limits.variants+". Remove some values, or list very different items separately.",field:"options"}}return{ok:true,options:out}}function countOptionCombinations(options){return(options||[]).reduce(function(n,o){return n*Math.max(1,(o.values||[]).length)},1)}function optionComboKey(values,options){if(!values||typeof values!=="object")return"";var parts=[];for(var i=0;i<options.length;i++){var o=options[i];var vid=values[o.id];if(!vid||!o.values.some(function(v){return v.id===vid}))return"";parts.push(o.id+"="+vid)}var extra=Object.keys(values).some(function(k){return!options.some(function(o){return o.id===k})});return extra?"":parts.join("|")}function optionComboLabel(values,options){return options.map(function(o){var vid=values&&values[o.id];var v=o.values.filter(function(x){return x.id===vid})[0];return v?v.label:"?"}).join(" / ")}function generateOptionCombinations(options){var combos=[{}];(options||[]).forEach(function(o){var next=[];combos.forEach(function(c){o.values.forEach(function(v){var copy={};Object.keys(c).forEach(function(k){copy[k]=c[k]});copy[o.id]=v.id;next.push(copy)})});combos=next});return combos}function planVariantChanges(options,existing,incoming){var byId={},byKey={};(existing||[]).forEach(function(e){byId[e.variantId]=e;var k=optionComboKey(e.values,options);if(k&&e.status!=="deleted"&&!byKey[k])byKey[k]=e});var seenKeys={},usedIds={};var rows=[];for(var i=0;i<(incoming||[]).length;i++){var inc=incoming[i]||{};var key=optionComboKey(inc.values,options);if(!key)return{ok:false,error:"Variant "+(i+1)+" does not have a value for every option.",index:i};if(seenKeys[key])return{ok:false,error:optionComboLabel(inc.values,options)+" is listed twice.",index:i};seenKeys[key]=true;var match=null;if(inc.variantId){match=byId[inc.variantId];if(!match||match.status==="deleted")return{ok:false,error:"Variant "+(i+1)+" is not part of this product. Please reload and try again.",index:i}}else if(byKey[key]){match=byKey[key]}if(match&&usedIds[match.variantId])return{ok:false,error:optionComboLabel(inc.values,options)+" is listed twice.",index:i};if(match)usedIds[match.variantId]=true;var active=inc.active!==false;rows.push({variantId:match?match.variantId:"",key:key,values:inc.values,label:optionComboLabel(inc.values,options),active:active,action:!match?"create":active?"update":"disable"})}var disabled=(existing||[]).filter(function(e){return!usedIds[e.variantId]&&e.status==="active"}).map(function(e){return{variantId:e.variantId,label:e.label||"",action:"disable"}});if(!rows.some(function(r){return r.active}))return{ok:false,error:"Switch on at least one combination that you sell.",index:-1};return{ok:true,rows:rows,disabled:disabled}}function optionValueStates(options,variants,optionId,picked){var opt=options.filter(function(o){return o.id===optionId})[0];var out={};if(!opt)return out;opt.values.forEach(function(val){var state="none";(variants||[]).forEach(function(v){if(!v.values||v.values[optionId]!==val.id)return;var fits=Object.keys(picked||{}).every(function(k){return k===optionId||!picked[k]||v.values[k]===picked[k]});if(!fits)return;var inStock=v.stockQty==null||v.stockQty>0;if(inStock)state="available";else if(state==="none")state="soldout"});out[val.id]=state});return out}function variantForSelection(options,variants,picked){var key=optionComboKey(picked,options);if(!key)return null;return(variants||[]).filter(function(v){return optionComboKey(v.values,options)===key})[0]||null}var PRICE_TIER_LIMITS={tiers:5,qtyMax:1e4,priceMax:1e6};function tierCents(n){return Math.round(Number(n)*100)/100}function tierWholeQty(n,lo){return typeof n==="number"&&isFinite(n)&&Math.floor(n)===n&&n>=lo&&n<=PRICE_TIER_LIMITS.qtyMax}function normalizePriceTiers(raw,basePrice,label){var what=label||"this item";if(raw===undefined||raw===null||raw==="")return{ok:true,tiers:[]};if(!Array.isArray(raw))return{ok:false,error:"Bulk prices for "+what+" could not be read."};var rows=raw.filter(function(t){return t&&!(String(t.minQty==null?"":t.minQty).trim()===""&&String(t.price==null?"":t.price).trim()==="")});if(rows.length>PRICE_TIER_LIMITS.tiers)return{ok:false,error:"Up to "+PRICE_TIER_LIMITS.tiers+" bulk prices for "+what+"."};var base=Number(basePrice);var tiers=[];for(var i=0;i<rows.length;i++){var q=Number(String(rows[i].minQty).trim());var pRaw=String(rows[i].price==null?"":rows[i].price).trim();var p=Number(pRaw);if(!tierWholeQty(q,2))return{ok:false,error:"Each bulk price for "+what+" needs a whole-number quantity of 2 or more."};if(pRaw===""||!isFinite(p)||p<=0||p>PRICE_TIER_LIMITS.priceMax)return{ok:false,error:"Enter a bulk price above 0 for "+q+"+ of "+what+"."};tiers.push({minQty:q,price:tierCents(p)})}tiers.sort(function(a,b){return a.minQty-b.minQty});for(var j=0;j<tiers.length;j++){if(j>0&&tiers[j].minQty===tiers[j-1].minQty)return{ok:false,error:"Two bulk prices for "+what+" start at "+tiers[j].minQty+"."};if(!(tiers[j].price<base))return{ok:false,error:"The bulk price for "+tiers[j].minQty+"+ of "+what+" must be lower than the normal price."};if(j>0&&!(tiers[j].price<tiers[j-1].price))return{ok:false,error:"Bulk prices for "+what+" must go down as the quantity goes up."}}return{ok:true,tiers:tiers}}function normalizeMinOrderQty(raw,label){var s=String(raw==null?"":raw).trim();if(s===""||s==="1")return{ok:true,value:""};var n=Number(s);if(!tierWholeQty(n,1))return{ok:false,error:"The minimum order for "+(label||"this item")+" must be a whole number from 1 to "+PRICE_TIER_LIMITS.qtyMax+"."};return{ok:true,value:n}}function tierUnitPrice(basePrice,tiers,qty){var base=tierCents(basePrice);var price=base;(tiers||[]).forEach(function(t){if(t&&Number(qty)>=Number(t.minQty)&&Number(t.price)>0)price=tierCents(t.price)});return Math.min(price,base)}if(typeof module!=="undefined"&&module.exports){module.exports={validateProductOptions:validateProductOptions,optionComboKey:optionComboKey,optionComboLabel:optionComboLabel,generateOptionCombinations:generateOptionCombinations,planVariantChanges:planVariantChanges,optionValueStates:optionValueStates,variantForSelection:variantForSelection,countOptionCombinations:countOptionCombinations,PRODUCT_OPTION_LIMITS:PRODUCT_OPTION_LIMITS,normalizePriceTiers:normalizePriceTiers,normalizeMinOrderQty:normalizeMinOrderQty,tierUnitPrice:tierUnitPrice,PRICE_TIER_LIMITS:PRICE_TIER_LIMITS}}